source:
flowchart TB
  subgraph TASK["ECS タスク"]
    AG@{ svc: "AWS Fargate", label: "エージェント（イメージを取得）" }
    APP@{ svc: "Amazon ECS", label: "コンテナのアプリ" }
  end
  ER@{ svc: "AWS IAM", label: "✔ A: タスク実行ロール" }
  TR@{ svc: "AWS IAM", label: "✔ B: タスクの IAM ロール" }
  ECR@{ svc: "Amazon ECR", label: "プライベートリポジトリ" }
  S3@{ svc: "Amazon S3", label: "バケット" }
  BADC["⚠ C: 取得の権限をタスクロールに付けても、取るのはエージェント"]
  BADD["⚠ D: S3 の権限を実行ロールに付けてもコンテナは使えない"]
  BADE["⚠ E: ECR を公開 → 権限の問題の答えにならない"]
  ER -- "取得の権限" --> AG
  AG == "イメージの取得" ==> ECR
  TR -- "S3 への書き込み" --> APP
  APP == "オブジェクトを書く" ==> S3
  BADC -.-> TR
  BADD -.-> ER
  BADE -.-> ECR
